import{_ as t,c as r,o as a,a5 as o}from"./chunks/framework.DuCYAsAJ.js";const b=JSON.parse('{"title":"术语表","description":"","frontmatter":{"title":"术语表","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#11","branch":"main","level":0,"order":11,"date":"2026-05-24T00:00:00.000Z"},"headers":[],"relativePath":"posts/projects/zfeed/11-glossary/index.md","filePath":"posts/projects/zfeed/11-glossary/index.md","lastUpdated":1779632679000}'),i={name:"posts/projects/zfeed/11-glossary/index.md"};function c(n,e,l,p,s,g){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/contentservice_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/contentservice_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userfavoritefeedlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userfavoritefeedlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userfavoritefeedlogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userfavoritefeedlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userpublishfeedlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userpublishfeedlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userpublishfeedlogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userpublishfeedlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher_test.go" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/like_strategy.go" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/like_strategy.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_operator.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_operator.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/repositories/count_value_repository.go" target="_blank" rel="noreferrer">app/rpc/count/internal/repositories/count_value_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/likelogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/likelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/likelogic_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/likelogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/unlikelogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/unlikelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config_env_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config_env_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchuserslogic.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchuserslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env" target="_blank" rel="noreferrer">deploy/.env</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/go.mod" target="_blank" rel="noreferrer">go.mod</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/hotrank/formula_bench_test.go" target="_blank" rel="noreferrer">pkg/hotrank/formula_bench_test.go</a></li></ul></details><p>本术语表定义 <code>zfeed</code> 生态中使用的代码库专属术语、架构模式和领域概念。它是面向新工程师的技术参考，用于理解自然语言概念如何映射到具体代码实体。</p><h2 id="核心领域术语" tabindex="-1">核心领域术语 <a class="header-anchor" href="#核心领域术语" aria-label="Permalink to &quot;核心领域术语&quot;">​</a></h2><h3 id="内容层级-content-hierarchy" tabindex="-1">内容层级（Content Hierarchy） <a class="header-anchor" href="#内容层级-content-hierarchy" aria-label="Permalink to &quot;内容层级（Content Hierarchy）&quot;">​</a></h3><p>系统使用“基础表 + 扩展表”模式管理不同媒体类型。</p><ul><li>Content（基础实体）：表示帖子的通用实体。它保存 <code>visibility</code>、<code>status</code>、<code>hot_score</code> 等元数据。</li><li>Article/Video（扩展实体）：某一内容类型的专属数据。文章包含标题和描述；视频包含 URL 和封面图。</li><li>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go#L35-L72" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go#35-72</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L181-L183" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#181-183</a></li></ul><h3 id="scene" tabindex="-1">Scene <a class="header-anchor" href="#scene" aria-label="Permalink to &quot;Scene&quot;">​</a></h3><p>“Scene” 是用于区分互动发生位置的枚举，例如点赞、评论或收藏发生在哪类目标上。这允许同一套 RPC 逻辑处理不同目标类型，例如点赞文章与点赞评论。</p><ul><li>实现：在 protobuf 中定义为 <code>interaction.Scene</code>。</li><li>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go#L19-L22" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go#19-22</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/likelogic_test.go#L160-L160" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/likelogic_test.go#160</a></li></ul><h3 id="viewerstate" tabindex="-1">ViewerState <a class="header-anchor" href="#viewerstate" aria-label="Permalink to &quot;ViewerState&quot;">​</a></h3><p>ViewerState 是内容详情获取期间使用的一种模式，会根据请求用户与内容之间的关系补充数据，例如 <code>IsLiked</code>、<code>IsFollowing</code>。</p><ul><li>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L1-L10" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#1-10</a>（通过逻辑流引用）。</li></ul><hr><h2 id="技术模式" tabindex="-1">技术模式 <a class="header-anchor" href="#技术模式" aria-label="Permalink to &quot;技术模式&quot;">​</a></h2><h3 id="transactional-outbox" tabindex="-1">Transactional Outbox <a class="header-anchor" href="#transactional-outbox" aria-label="Permalink to &quot;Transactional Outbox&quot;">​</a></h3><p><code>interaction-rpc</code> 服务使用的一种可靠性模式。事件不会直接发布到 Kafka，而是和业务状态变更放在同一个事务中写入 MySQL 表（<code>zfeed_like_event_outbox</code>）。随后由独立 relay 进程轮询该表并推送到 Kafka。</p><ul><li>实现：<code>zfeed_like_event_outbox</code> 表。</li><li>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L76-L76" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#76</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L146-L162" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#146-162</a></li></ul><h3 id="基于-cursor-的分页-cursor-based-pagination" tabindex="-1">基于 Cursor 的分页（Cursor-based Pagination） <a class="header-anchor" href="#基于-cursor-的分页-cursor-based-pagination" aria-label="Permalink to &quot;基于 Cursor 的分页（Cursor-based Pagination）&quot;">​</a></h3><p>内容列表和搜索结果的主要分页方式。它使用一个 ID，通常是 <code>ContentID</code> 或 <code>UserID</code>，作为指向上一页最后一项的指针，从而在数据更新期间保持结果稳定。</p><ul><li>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L131-L134" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#131-134</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchuserslogic.go#L141-L144" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchuserslogic.go#141-144</a></li></ul><h3 id="snapshot-分页-snapshot-pagination" tabindex="-1">Snapshot 分页（Snapshot Pagination） <a class="header-anchor" href="#snapshot-分页-snapshot-pagination" aria-label="Permalink to &quot;Snapshot 分页（Snapshot Pagination）&quot;">​</a></h3><p><code>search-rpc</code> 中的一种高级分页模式，会把整个结果集作为“snapshot”缓存在 Redis 中，以便在底层数据变化时仍能为深度分页提供稳定、一致的排序。</p><ul><li>实现：<code>searchContentsWithSnapshot</code> 和 <code>loadSearchSnapshot</code>。</li><li>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L54-L59" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#54-59</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L159-L221" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#159-221</a></li></ul><hr><h2 id="搜索与缓存" tabindex="-1">搜索与缓存 <a class="header-anchor" href="#搜索与缓存" aria-label="Permalink to &quot;搜索与缓存&quot;">​</a></h2><h3 id="查询归一化-query-normalization" tabindex="-1">查询归一化（Query Normalization） <a class="header-anchor" href="#查询归一化-query-normalization" aria-label="Permalink to &quot;查询归一化（Query Normalization）&quot;">​</a></h3><p>查询归一化是对搜索查询进行清理、分词和哈希的过程，用于提升缓存命中率并避免重复处理。</p><ul><li>实现：<code>l.svcCtx.NormalizeQuery(in.GetQuery())</code>。</li><li>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L36-L39" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#36-39</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchuserslogic.go#L39-L42" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchuserslogic.go#39-42</a></li></ul><h3 id="缓存层级-cache-tiers" tabindex="-1">缓存层级（Cache Tiers） <a class="header-anchor" href="#缓存层级-cache-tiers" aria-label="Permalink to &quot;缓存层级（Cache Tiers）&quot;">​</a></h3><p>搜索服务使用两个特定缓存层：</p><ol><li>Query Cache：缓存某个搜索关键词对应的结果 ID。</li><li>Doc Cache：缓存实体（User/Content）的完整摘要，避免补全阶段访问数据库。</li></ol><ul><li>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go#L19-L21" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go#19-21</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config_env_test.go#L23-L25" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config_env_test.go#23-25</a></li></ul><hr><h2 id="架构映射" tabindex="-1">架构映射 <a class="header-anchor" href="#架构映射" aria-label="Permalink to &quot;架构映射&quot;">​</a></h2><h3 id="自然语言到代码实体-搜索流程" tabindex="-1">自然语言到代码实体：搜索流程 <a class="header-anchor" href="#自然语言到代码实体-搜索流程" aria-label="Permalink to &quot;自然语言到代码实体：搜索流程&quot;">​</a></h3><p>下图将一次搜索请求的逻辑步骤映射到具体内部逻辑函数和配置开关。</p><p>标题：搜索请求逻辑流程</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L31-L91" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#31-91</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go#L13-L16" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go#13-16</a></p><h3 id="自然语言到代码实体-互动可靠性" tabindex="-1">自然语言到代码实体：互动可靠性 <a class="header-anchor" href="#自然语言到代码实体-互动可靠性" aria-label="Permalink to &quot;自然语言到代码实体：互动可靠性&quot;">​</a></h3><p>下图展示“点赞”动作如何实现，以保证 MySQL 和 Count Service 之间的数据一致性。</p><p>标题：互动与计数流水线</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go#L46-L79" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go#46-79</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L75-L76" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#75-76</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/like_strategy.go#L1-L20" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/like_strategy.go#1-20</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_operator.go#L1-L15" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_operator.go#1-15</a></p><hr><h2 id="表格汇总-关键基础设施组件" tabindex="-1">表格汇总：关键基础设施组件 <a class="header-anchor" href="#表格汇总-关键基础设施组件" aria-label="Permalink to &quot;表格汇总：关键基础设施组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>代码引用</th><th>在 zfeed 中的用途</th></tr></thead><tbody><tr><td>Etcd</td><td><code>search.yaml</code> 中的 <code>Etcd.Hosts</code></td><td>gRPC 客户端服务发现。</td></tr><tr><td>Kafka</td><td><code>.env</code> 中的 <code>KAFKA_BROKERS</code></td><td>互动与计数的异步事件总线。</td></tr><tr><td>Redis</td><td><code>Config</code> 中的 <code>RedisConfig</code></td><td>会话存储、搜索 snapshot 和热门 Feed 排行。</td></tr><tr><td>Canal</td><td><code>.env</code> 中的 <code>CANAL_PORT</code></td><td>基于 binlog 更新计数的 CDC（Change Data Capture）。</td></tr><tr><td>XXL-JOB</td><td><code>XXL_JOB_ADMIN_ADDR</code></td><td>用于热度排行衰减和 snapshot 清理的分布式 cron 任务。</td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L12-L100" target="_blank" rel="noreferrer">deploy/.env#12-100</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml#L33-L48" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml#33-48</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go#L11-L12" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go#11-12</a></p>',47)])])}const d=t(i,[["render",c]]);export{b as __pageData,d as default};
